/** The parts of the two wdio configs that must stay identical — see
 * `./obsidian-target.mts` for what happened last time they drifted. */

import * as fsp from 'node:fs/promises';
import * as path from 'node:path';
import { browser } from '@wdio/globals';

/**
 * How many Obsidian instances run at once; 1 unless E2E_MAX_INSTANCES says
 * otherwise. Each is a full Electron renderer, and `waitBudget` in
 * ./helpers.ts widens the harness timeouts off this value, so raising it
 * changes how the suite behaves and not just how fast it finishes.
 */
export function maxInstances(): number {
  const raw = process.env.E2E_MAX_INSTANCES?.trim();
  if (!raw) return 1;
  const n = Number(raw);
  if (!Number.isInteger(n) || n < 1) {
    throw new Error(`E2E_MAX_INSTANCES must be a positive integer, got ${JSON.stringify(raw)}`);
  }
  return n;
}

/** Where `screenshotOnFailure` writes. CI uploads this only when a job fails. */
export const FAILURE_SCREENSHOT_DIR = path.join(
  process.cwd(),
  '.obsidian-cache',
  'failure-screenshots',
);

/** `a/b: c` -> `a-b-c`, so a test title is safe as a file name. */
function slugify(text: string): string {
  return text
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 120);
}

/**
 * An `afterTest` hook that captures the screen for a failing test.
 *
 * A capture failure is swallowed: when the session itself has died, the useful
 * error is the test's own, not "could not screenshot".
 */
export function screenshotOnFailure(label: string) {
  return async function (
    test: { title: string; parent: string },
    _context: unknown,
    { passed }: { passed: boolean },
  ): Promise<void> {
    if (passed) return;
    try {
      await fsp.mkdir(FAILURE_SCREENSHOT_DIR, { recursive: true });
      const name = slugify(`${label}-${test.parent}-${test.title}`);
      await browser.saveScreenshot(path.join(FAILURE_SCREENSHOT_DIR, `${name}.png`));
    } catch (e) {
      console.warn(`[e2e] could not capture a failure screenshot for "${test.title}": ${String(e)}`);
    }
  };
}

import * as path from 'node:path';
import * as url from 'node:url';
import { resolveObsidianTarget } from './obsidian-target.mjs';
import { maxInstances, screenshotOnFailure } from './wdio.shared.mjs';

const e2eDir = path.dirname(url.fileURLToPath(import.meta.url));
const root = path.resolve(e2eDir, '..');

/**
 * Which Obsidian to run, and where it is cached — resolved by
 * `./obsidian-target.mts`, shared with the mobile config so the two cannot
 * drift apart again.
 *
 * Why the version matters (docs/research/04 Q21, Q27): a user-reported
 * redo-cursor bug went unreproducible for three rounds because the behavior
 * causing it entered `@codemirror/commands` 6.10.2 and the newest STABLE
 * Obsidian bundles an older CM6 while the reporter was on a 1.13.x beta. Later,
 * a keymap investigation cost several more sessions with the harness on 1.12.7
 * and the reporter on 1.13.3. Both times the harness was internally consistent
 * and green.
 *
 * To pre-download a beta WITHOUT disabling 2FA (the env vars require 2FA off):
 *
 *     npm run obsidian:fetch -- -v 1.13.3
 *
 * Use that script rather than `npx obsidian-launcher download` directly: the
 * CLI defaults to `~/.obsidian-cache` while this harness has its own, so a bare
 * CLI download lands where the harness never looks and then fails as "Insiders
 * account is required" — a download that SUCCEEDED, reported as a credentials
 * problem.
 */
const { browserVersion, cacheDir } = await resolveObsidianTarget(root, '');

export const config: WebdriverIO.Config = {
  runner: 'local',
  framework: 'mocha',
  specs: [path.join(e2eDir, 'specs/**/*.e2e.ts')],
  // Safe to raise: the service gives every session its own copy of the vault
  // (`copy` defaults to true) and its own --user-data-dir, so workers cannot
  // observe each other's writes whatever the specs do. See ./wdio.shared.mts.
  maxInstances: maxInstances(),

  capabilities: [
    {
      browserName: 'obsidian',
      browserVersion,
      // Keep Electron rendering at full rate even when the test window is
      // occluded or the machine's display is asleep — without these,
      // Chromium throttles frame production for background windows, and
      // screenshot capture (a renderer round-trip) times out while plain
      // script execution keeps working. This is the exact signature of the
      // "screenshot-heavy tests time out under local load, pass on a fresh
      // CI runner" flake documented in tasks.md 5.7 — reproduced locally
      // during the hardening pass on code that had passed the same spec
      // minutes earlier, with only the machine's session state changed.
      'goog:chromeOptions': {
        args: [
          '--disable-renderer-backgrounding',
          '--disable-background-timer-throttling',
          '--disable-backgrounding-occluded-windows',
        ],
      },
      'wdio:obsidianOptions': {
        installerVersion: 'earliest',
        plugins: [
          root, // manifest.json + main.js (run `npm run build:plugin` first)
          // Conflicting-plugin stub for the coexistence warning test; starts
          // disabled, enabled by shell.e2e.ts.
          { path: path.join(e2eDir, 'fixtures/obsidian-outliner-stub'), enabled: false },
        ],
        vault: path.join(root, 'test-vault'),
      },
    },
  ],

  /**
   * Arm the notice recorder before any spec acts. Notices live ~1500ms and
   * `waitForNotice` polls over WebDriver, so a notice produced by the very
   * action a spec is waiting on can vanish between polls; recording from
   * session start removes that race even for specs that produce a notice
   * before touching any note helper (see `armNoticeRecorder`).
   */
  before: async function () {
    const { armNoticeRecorder } = await import('./helpers.js');
    await armNoticeRecorder();
  },

  afterTest: screenshotOnFailure('desktop'),

  services: ['obsidian'],
  reporters: ['obsidian'],

  cacheDir,
  mochaOpts: {
    ui: 'bdd',
    timeout: 60_000,
  },
  logLevel: 'warn',
};

import * as path from 'node:path';
import * as url from 'node:url';
import { resolveObsidianTarget } from './obsidian-target.mjs';
import { maxInstances, screenshotOnFailure } from './wdio.shared.mjs';

const e2eDir = path.dirname(url.fileURLToPath(import.meta.url));
const root = path.resolve(e2eDir, '..');

/** Shared with wdio.conf.mts — see `./obsidian-target.mts`. Previously this
 * file had its own copy, which honored neither `OBSIDIAN_VERSION` nor a
 * configurable cache, so pinning a version silently applied to the desktop
 * suite only. */
const { browserVersion, cacheDir } = await resolveObsidianTarget(root, ' mobile');

/**
 * Mobile-emulation variant of wdio.conf.mts: identical plugin/vault/specs,
 * run under Obsidian's own `app.emulateMobile()` instead — still the
 * Electron desktop app under a phone-sized viewport, not the real
 * Capacitor mobile app. What that does and does not catch is spelled out on
 * `IS_MOBILE_RUN` in ./helpers.ts, next to the specs that skip themselves
 * here: real mouse drags become touch gestures under emulation, so a
 * drag-based selection test is measuring something that does not exist.
 */
export const config: WebdriverIO.Config = {
  runner: 'local',
  framework: 'mocha',
  specs: [path.join(e2eDir, 'specs/**/*.e2e.ts')],
  // Safe to raise: the service gives every session its own copy of the vault
  // (`copy` defaults to true) and its own --user-data-dir, so workers cannot
  // observe each other's writes whatever the specs do. See ./wdio.shared.mts.
  maxInstances: maxInstances(),

  capabilities: [
    {
      browserName: 'obsidian',
      browserVersion,
      'wdio:obsidianOptions': {
        installerVersion: 'earliest',
        plugins: [
          root,
          { path: path.join(e2eDir, 'fixtures/obsidian-outliner-stub'), enabled: false },
        ],
        vault: path.join(root, 'test-vault'),
        emulateMobile: true,
      },
      'goog:chromeOptions': {
        // Same anti-throttling flags as wdio.conf.mts — see the comment
        // there for the occluded-window screenshot-timeout flake they fix.
        args: [
          '--disable-renderer-backgrounding',
          '--disable-background-timer-throttling',
          '--disable-backgrounding-occluded-windows',
        ],
        mobileEmulation: {
          // Phone-sized viewport; Obsidian's tablet UI switches in around
          // width/height >= 600, so this stays in "phone" mode. Push both
          // dimensions past 600 to spot-check the tablet layout instead.
          deviceMetrics: { width: 390, height: 844 },
        },
      },
    },
  ],

  /**
   * Arm the notice recorder before any spec acts. Notices live ~1500ms and
   * `waitForNotice` polls over WebDriver, so a notice produced by the very
   * action a spec is waiting on can vanish between polls; recording from
   * session start removes that race even for specs that produce a notice
   * before touching any note helper (see `armNoticeRecorder`).
   */
  before: async function () {
    const { armNoticeRecorder } = await import('./helpers.js');
    await armNoticeRecorder();
  },

  afterTest: screenshotOnFailure('mobile'),

  services: ['obsidian'],
  reporters: ['obsidian'],

  cacheDir,
  mochaOpts: {
    ui: 'bdd',
    timeout: 60_000,
  },
  logLevel: 'warn',
};

