1	/**
2	 * The dev-loop entry point for iterating on ONE e2e test: builds the plugin,
3	 * then invokes wdio directly against a single spec file (optionally further
4	 * narrowed to a single test by name), skipping `run-e2e.mjs`'s whole-group
5	 * dispatch. Reserve `run-e2e.mjs` (`npm run test:e2e[:mobile]`) for a final
6	 * check before pushing — see CLAUDE.md's "E2E testing" section for why.
7	 *
8	 *   node scripts/e2e-narrow.mjs <spec> [test-name-grep] [--mobile]
9	 *
10	 * `<spec>` is matched against `e2e/specs/*.e2e.ts` by substring on the
11	 * filename (case-insensitive) — `77`, `footer-controls`, and
12	 * `77-footer-controls` all resolve to the same file — or it can be a real
13	 * path to a spec file. An ambiguous substring lists every match and exits
14	 * rather than guessing.
15	 *
16	 * `[test-name-grep]` becomes `--mochaOpts.grep`, mocha's own substring/regex
17	 * match against full test titles (`describe > it`), so it works with no
18	 * changes to the specs themselves.
19	 *
20	 * This still runs the plugin build, the backlink-hub generator, and the vault
21	 * drift snapshot/restore that `run-e2e.mjs` runs — measured at under half a
22	 * second combined (`time` against each in isolation), which is not where the
23	 * minutes went. What made the whole-group loop slow was Obsidian launching
24	 * once per spec FILE in the group (up to 10), not this setup — so the actual
25	 * lever here is `--spec` targeting a single file, and this script does not
26	 * try to skip the cheap, correctness-preserving steps around it.
27	 */
28	
29	import { spawnSync } from 'node:child_process';
30	import { existsSync, readdirSync } from 'node:fs';
31	import { fileURLToPath } from 'node:url';
32	import * as path from 'node:path';
33	import { binPath } from './bin-path.mjs';
34	
35	const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
36	const specDir = path.join(root, 'e2e', 'specs');
