  suite = run(wdio, wdioArgs, mobile ? { OBSIDIAN_E2E_MOBILE: '1' } : {});
} finally {
  const cleanup = drift();
  process.exitCode = suite !== 0 ? suite : cleanup !== 0 ? 1 : 0;
}

